\begin{tikzpicture}[font=\sffamily, thick, >=Stealth]
  % Axes
  \draw[->] (0,0) -- (7,0) node[right, font=\sffamily\small] {Reaction pathway};
  \draw[->] (0,0) -- (0,5.5) node[above, font=\sffamily\small] {Energy};

  % Reactants and products energy levels
  \coordinate (Reactants) at (0.5, 1.5);
  \coordinate (Products) at (6, 0.8);

  % Draw reactants and products lines
  \draw (Reactants) -- ++(1,0) node[midway, above, font=\sffamily\small] {Reactants};
  \draw (Products) -- ++(1,0) node[midway, above, font=\sffamily\small] {Products};

  % Curves
  % Uncatalysed curve (higher peak)
  \draw[smooth] (Reactants) .. controls (2.2, 4.8) and (3.8, 4.8) .. (Products);

  % Catalysed curve (lower peak)
  \draw[smooth, dashed] (Reactants) .. controls (2.5, 3.2) and (3.5, 3.2) .. (Products);

  % Peaks coordinates for labeling
  \coordinate (Peak1) at (3, 4.15);
  \coordinate (Peak2) at (3, 2.75);

  % Labels for curves
  \node[above, font=\sffamily\small] at (3, 4.3) {without catalyst};
  \node[above right, font=\sffamily\small] at (3.5, 2.7) {with catalyst};

  % Energy levels / dashed lines for activation energies and enthalpy change
  \draw[thin, dashed] (0, 1.5) -- (1.5, 1.5);
  \draw[thin, dashed] (0, 0.8) -- (6, 0.8);

  % Peak energy level for uncatalysed
  \draw[thin, dashed] (0, 4.15) -- (Peak1);

  % Double-headed arrows for activation energies
  \draw[<->] (2.2, 1.5) -- node[right, font=\sffamily\small] {$E_a$ (without)} (2.2, 4.15);
  \draw[<->] (4.2, 1.5) -- node[right, font=\sffamily\small] {$E_a$ (with)} (4.2, 2.75);

  % Enthalpy change delta H
  \draw[<->] (6.5, 1.5) -- node[right, font=\sffamily\small] {$\Delta H$} (6.5, 0.8);

  % Figure caption
  \node at (3.5, -0.8) {Fig. 4.1};

\end{tikzpicture}
